-- catalogo-service · fichas de producto más completas: presentación, modo de uso y para quién es.
-- Solo cambia descripciones (contenido); idempotente.
USE catalogo_db;
UPDATE productos SET descripcion = CASE slug
  WHEN 'tiras-res-deshidratadas' THEN 'Jerky de res de un solo ingrediente enriquecido con glucosamina y condroitina. Ideal para perros activos y senior que necesitan cuidar cadera y articulaciones. Dale de 1 a 3 tiras al día según su tamaño, como premio o en el entrenamiento. Sin conservantes ni colorantes.'
  WHEN 'correa-collar-reflectivo' THEN 'Set de collar y correa de nylon resistente con costuras reflectivas que se ven a más de 50 m con las luces de un carro: paseos nocturnos más seguros. Hebilla de liberación rápida, argolla de aluminio para la placa y correa de 1,5 m con mango acolchado.'
  WHEN 'panoleta-bandana' THEN 'Bandana 100% algodón, suave y lavable a máquina, con broche ajustable que no aprieta. Estampados que no destiñen. Mide el cuello de tu perro antes de elegir la talla: si queda entre dos, elige la menor.'
  WHEN 'sudadera-perro' THEN 'Sudadera de felpa suave con capucha y abertura en la espalda para pasar la correa del arnés. Mantiene a tu perro abrigado en los días fríos y después del baño. Lavable a máquina en agua fría; mide el largo del lomo para elegir la talla.'
  WHEN 'sueter-tejido' THEN 'Suéter de tejido acanalado, cálido y elástico, con cuello alto que protege del frío sin incomodar. Ideal para razas de pelo corto, cachorros y perros senior. Lavar a mano o en ciclo delicado.'
  WHEN 'alimento-humedo-gato-pollo' THEN 'Trozos de pechuga de pollo real en caldo natural. Alta hidratación y proteína, sin cereales ni colorantes: ayuda a los gatos que toman poca agua. Sírvelo solo o como complemento de las croquetas; una vez abierto, refrigera y úsalo en 48 h.'
  WHEN 'croquetas-gato-salmon' THEN 'Fórmula completa para gato adulto con salmón como primer ingrediente, taurina para corazón y vista, y fibra natural para el control de bolas de pelo. Croqueta pequeña, fácil de masticar. Cambia el alimento poco a poco durante 7 días.'
  WHEN 'varita-plumas-gato' THEN 'Estimula el instinto cazador de tu gato con plumas naturales y un cascabel. Mango flexible de 60 cm para jugar sin que te arañe. Úsala en sesiones de 10 a 15 minutos y guárdala al terminar para que no se trague las plumas.'
  WHEN 'cama-nube-gato' THEN 'Cama redonda de peluche extra suave con borde elevado que da sensación de seguridad y guarda el calor. Base antideslizante. Funda lavable a máquina; también sirve para perros pequeños de hasta 5 kg.'
  WHEN 'hojuelas-tropicales' THEN 'Alimento completo en hojuelas con espirulina que realza el color natural de tus peces tropicales. Da solo lo que coman en 2 o 3 minutos, dos veces al día, para no ensuciar el agua.'
  WHEN 'kit-acuario-40l' THEN 'Kit para empezar: pecera de vidrio de 40 litros, filtro silencioso, iluminación LED y calentador regulable. Deja el agua circular una semana con el filtro encendido antes de poner los peces.'
  WHEN 'mezcla-semillas-hamster' THEN 'Semillas, granos, frutas deshidratadas y vegetales para una dieta variada y balanceada de hámsters y jerbos. Complementa con verdura fresca y cambia el agua todos los días.'
  WHEN 'rueda-silenciosa' THEN 'Rueda de ejercicio con rodamiento silencioso y superficie antideslizante para que tu pequeño se ejercite día y noche sin despertarte. Para hámsters y jerbos; no apta para conejos ni cobayas. Incluye soporte para la jaula.'
  WHEN 'semillas-periquitos' THEN 'Mijo, alpiste y avena seleccionados, enriquecidos con vitaminas y minerales para periquitos y canarios. Retira las cáscaras a diario y ofrece fruta y verdura fresca dos veces por semana.'
  WHEN 'columpio-percha-madera' THEN 'Columpio de madera sin tratar con cuentas de colores para entretener a tu ave y cuidar sus patas. Se cuelga con gancho de acero inoxidable. Para periquitos, agapornis y cotorras pequeñas.'
  WHEN 'grillos-deshidratados' THEN 'Fuente natural de proteína para geckos, dragones barbudos y otros insectívoros. Hidrátalos unos minutos en agua antes de servir y espolvorea calcio si tu veterinario lo indica.'
  WHEN 'lampara-uvb-terrario' THEN 'Emite rayos UVB y calor para la síntesis de vitamina D3 y el metabolismo del calcio de tu reptil. Colócala a 30 cm del sustrato, enciéndela 10 a 12 horas al día y cámbiala cada 6 meses: el UVB se agota aunque siga alumbrando.'
  WHEN 'shampoo-avena-perro' THEN 'Limpia sin resecar la piel sensible o con dermatitis. Con avena coloidal y aloe vera, pH balanceado para perros y sin perfume fuerte. Deja actuar 5 minutos y enjuaga bien. Recomendado por nuestros veterinarios para baños frecuentes.'
  WHEN 'arena-aglomerante-gato' THEN 'Arena de bentonita que forma bloques firmes que se retiran fácil, con control de olores natural y baja generación de polvo. Sin aroma, para gatos sensibles. Llena el arenero con 5 a 7 cm y retira los bloques todos los días.'
  WHEN 'pelota-caucho-indestructible' THEN 'Pelota de caucho natural resistente a mordidas fuertes; rebota de forma irregular para que el juego no sea predecible y se puede rellenar con premios. Lávala con agua y jabón. Elige un tamaño que tu perro no pueda tragar.'
  WHEN 'heno-timothy-conejo' THEN 'Heno de primer corte rico en fibra, esencial para la digestión y el desgaste dental de conejos, cobayas y chinchillas. Debe estar siempre disponible: es la base de su dieta. Guárdalo en un lugar seco y ventilado.'
  ELSE descripcion END;
